// The Dealshape logo: mark plus wordmark, from public/brand/wordmark.svg (generated by docs/brand/make_logo.py). Sizes in logo.js.
// BrandBlock: the logo alone, in every top bar (11 Nov: the tagline is gone from the page headers; the landing page keeps it).
import { NAME } from "./brand.js";
import { TOP_BAR_LOGO_HEIGHT, logoSize } from "./logo.js";

export default function Logo({ height = TOP_BAR_LOGO_HEIGHT }) {
  return <img className="brand-logo" src="/brand/wordmark.svg" alt={NAME} {...logoSize(height)} />;
}

export function BrandBlock({ className = "" }) {
  return (
    <span className={`brand-block ${className}`.trim()}>
      <Logo />
    </span>
  );
}

// 19 Nov: the logo as the route back to the landing page (#welcome), on the deal list and the live deal page. The locked record keeps the plain BrandBlock.
// The class goes on the link, so a rule that hides the brand line (phone width) hides the whole link.
export function BrandLink({ className = "" }) {
  return (
    <a className={`brand-link ${className}`.trim()} href="#welcome" aria-label={`${NAME} \u2014 overview`}>
      <BrandBlock />
    </a>
  );
}
